import{_ as o,o as t,c as d,a5 as c}from"./chunks/framework.DJo0M80U.js";const f=JSON.parse('{"title":"六、测试","description":"","frontmatter":{"title":"六、测试","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","微服务","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第九部分：微服务/01-微服务入门/微服务入门级教程/六、测试.md","filePath":"posts/java快速入门/第九部分：微服务/01-微服务入门/微服务入门级教程/六、测试.md"}'),a={name:"posts/java快速入门/第九部分：微服务/01-微服务入门/微服务入门级教程/六、测试.md"};function s(l,e,p,_,n,i){return t(),d("div",null,[...e[0]||(e[0]=[c("<div><p>接下来我们测试一下通过网关访问我们的<code>client</code>服务，如何访问呢</p><p>前面我们说到网关是通过服务名，去注册中心寻找相应的节点的，假如我们访问<code>localhost:8083/client/student/detail</code>，那么它就会去服务注册中心寻找叫做<code>client</code>的服务节点，并将后面的<code>/student/detail</code>转发到对应的节点，所以最后访问的真正地址也就是我们的<code>localhost:8081/student/list</code>。如果有多个相同名称的节点，则会以负载均衡的方式去分配到不同的服务节点。当然了，这都是<code>gateway</code>默认的转发方式，它有很多灵活的转发方式，都可以配置，比如忽略服务名前缀啊、从端口号后的第几个路径开始截图转发等等。</p><p>也就是说，网关默认的访问方式是：主机名<code>(</code>或者<code>IP</code>、域名<code>):</code>网关端口号<code>/</code>服务名称<code>/</code>请求的<code>url</code></p><p>落实到我们这个例子里，就是<code>localhost:8083/client/role/detail</code>，访问效果：</p><p>可以看到，张三和李四是交替出现的，<code>Gateway</code>网关为我们实现了负载均衡。</p><p><code>Gateway</code>的玩法有很多，由于篇幅原因以后再给大家介绍。</p></div>",1)])])}const m=o(a,[["render",s]]);export{f as __pageData,m as default};
